/// <summary>
/// Construct method
/// </summary>
/// <returns>Instance of <c>METSalesItemSubstituteSearchParameters</c></returns>
public static METSalesItemSubstituteSearchParameters construct()
{
    return new METSalesItemSubstituteSearchParameters();
}

/// <summary>
/// Parm method for item number
/// </summary>
/// <param name = "_itemId">Item number</param>
/// <returns>Item number</returns>
final public ItemId parmItemId(ItemId _itemId = itemId)
{
    itemId = _itemId;
    return itemId;
}

/// <summary>
/// Parm method for customer account
/// </summary>
/// <param name = "_custAccount">Customer account</param>
/// <returns>Customer account</returns>
final public CustAccount parmCustAccount(CustAccount _custAccount = custAccount)
{
    custAccount = _custAccount;
    return custAccount;
}

/// <summary>
/// Parm method for inventory dimensions
/// </summary>
/// <param name = "_inventDim">Inventory dimensions</param>
/// <returns>Inventory dimensions</returns>
final public InventDim parmInventDim(InventDim _inventDim = inventDim)
{
    inventDim = _inventDim;
    return inventDim;
}
